void tach_ign_on (void * arg)
{	
  if(!tach_vars.flag_ign)
    {
      tach_vars.flag_ign = TRUE ;
      
      #if DBG_TACH == 1
        tach_dbg_print("\nTach Ignition On", NULL, NULL);
      #endif
      
      tach_enable () ;
    }
}
//--------------------------------------------------------------------------//
void tach_rs_ign_on (void * arg)
{	
  if(!tach_vars.flag_rs_ign)
    {
      tach_vars.flag_rs_ign = TRUE ;
      
      #if DBG_TACH == 1
        tach_dbg_print("\nTach Rs Ignition On", NULL, NULL);
      #endif
      
      tach_enable () ;
    }
}
//--------------------------------------------------------------------------//

void tach_ign_off (void * arg)
{	
  if(tach_vars.flag_ign)
    {	
      tach_vars.flag_ign = FALSE ;

      #if DBG_TACH == 1
        tach_dbg_print("\nTach Ignition Off", NULL, NULL);
      #endif

      tach_disable () ;
    }    
}
//--------------------------------------------------------------------------//
void tach_rs_ign_off (void * arg)
{	
  if(tach_vars.flag_rs_ign)
    {	
      tach_vars.flag_rs_ign = FALSE ;

      #if DBG_TACH == 1
        tach_dbg_print("\nTach Rs Ignition Off", NULL, NULL);
      #endif

      tach_disable () ;
    }
}
